"""Self-Consistency baseline: majority vote over K reasoning traces with math equivalence."""
from __future__ import annotations

from utils.math_equiv import group_equivalent_answers
from sica.pipeline import _group_logic_answers


class SelfConsistency:

    def run(self, problem: dict, traces: list[str], answers: list[str]) -> dict:
        """Select answer by majority vote with equivalence-aware grouping."""
        valid = [a.strip() for a in answers if a.strip()]
        if not valid:
            return {"answer": "", "vote_count": 0, "total_traces": len(traces), "vote_distribution": {}}

        dataset = problem.get("dataset", "")
        if dataset in ("proofwriter", "folio"):
            groups = _group_logic_answers(valid)
        else:
            groups = group_equivalent_answers(valid)
        best_answer = max(groups, key=lambda k: len(groups[k]))
        best_count = len(groups[best_answer])
        vote_distribution = {k: len(v) for k, v in groups.items()}

        return {
            "answer": best_answer,
            "vote_count": best_count,
            "total_traces": len(traces),
            "vote_distribution": vote_distribution,
        }

"""
Invariant consensus scorer with A+C improvement:
  A (normal mode): score = positive_weight - alpha * negative_weight
  C (fallback mode): when satisfied_ratio < threshold, score = -excluded_exposure
"""
from __future__ import annotations

import logging
from collections import Counter

from .z3_maxsat import MaxSATResult

logger = logging.getLogger(__name__)


class InvariantScorer:

    def __init__(self, alpha: float = 0.5, fallback_threshold: float = 0.2):
        self.alpha = alpha
        self.fallback_threshold = fallback_threshold

    def score(
        self,
        maxsat_result: MaxSATResult,
        traces: list[dict],
        candidates: list[str],
    ) -> dict[str, float]:
        """Score each candidate answer using A+C strategy.

        Normal mode (A): score = Σw(satisfied ∩ traces) - α·Σw(excluded ∩ traces)
        Fallback mode (C): score = -Σw(excluded ∩ traces)
        Switches to fallback when satisfied_ratio < fallback_threshold.
        """
        answer_traces: dict[str, set[int]] = {}
        for t in traces:
            ans = str(t.get("answer", "")).strip()
            idx = t.get("trace_idx", 0)
            answer_traces.setdefault(ans, set()).add(idx)

        n_satisfied = len(maxsat_result.satisfied)
        n_excluded = len(maxsat_result.excluded)
        n_total = n_satisfied + n_excluded

        if n_total == 0:
            return {str(c).strip(): 0.0 for c in candidates}

        satisfied_ratio = n_satisfied / n_total
        fallback = satisfied_ratio < self.fallback_threshold

        logger.info(
            "Scorer mode=%s  satisfied_ratio=%.3f (%d/%d)  alpha=%.2f  threshold=%.2f",
            "FALLBACK" if fallback else "NORMAL",
            satisfied_ratio, n_satisfied, n_total,
            self.alpha, self.fallback_threshold,
        )

        scores: dict[str, float] = {}
        for cand in candidates:
            cand_key = str(cand).strip()
            cand_traces = answer_traces.get(cand_key, set())

            excluded_exposure = 0.0
            for uc in maxsat_result.excluded:
                if set(uc.source_traces) & cand_traces:
                    excluded_exposure += uc.weight

            if fallback:
                scores[cand_key] = -excluded_exposure
            else:
                positive = 0.0
                for uc in maxsat_result.satisfied:
                    if set(uc.source_traces) & cand_traces:
                        positive += uc.weight
                scores[cand_key] = positive - self.alpha * excluded_exposure

            logger.debug(
                "  candidate=%s  score=%.2f  traces=%s", cand_key, scores[cand_key], cand_traces,
            )

        return scores

    def select_answer(
        self,
        scores: dict[str, float],
        answer_counts: dict[str, int] | None = None,
    ) -> str:
        """Select the highest-scoring answer. Break ties by frequency."""
        if not scores:
            return ""
        max_score = max(scores.values())
        top = [a for a, s in scores.items() if s == max_score]
        if len(top) == 1:
            return top[0]
        if answer_counts:
            return max(top, key=lambda a: answer_counts.get(a, 0))
        return top[0]

\paragraph{Parameters.} $K{=}12$ traces at $T{=}0.7$, extraction at $T_{\text{ext}}{=}0.3$, $\alpha{=}0.5$, Z3 timeout 10s (K-sensitivity and extraction-temperature analysis in Appendix~\ref{app:sensitivity}). McNemar exact test ($\alpha{=}0.05$); 95\% bootstrap CIs ($10{,}000$ resamples; Appendix~\ref{app:bootstrap}) for $n \geq 200$. SICA incurs $4.5{\times}$ SC wall-clock; extraction accounts for 76\% of overhead.

\subsection{Main Results}

\looseness=-1 Table~\ref{tab:main_results} reports accuracy across all non-degenerate self-extraction conditions sorted by SC baseline. Two confirmatory conditions show significant degradation after Benjamini--Hochberg (BH) FDR control ($m{=}6$; multi-seed aggregates and extensions are exploratory): Mistral-7B on ProofWriter ($-2.83$\,pp, raw $p = 0.014$, adj.\ $p = 0.042$) and Qwen2.5-14B on ProofWriter ($-2.50$\,pp, raw $p = 0.011$, adj.\ $p = 0.042$). No condition shows a significant positive effect. An aggregate sign test yields 8 positive and 7 negative $\Delta$ values ($p = 1.00$, two-sided). When SICA and SC disagree, SC selects the correct answer $2.6\times$ more often (139 vs.\ 53 across conditions); constraint-based reweighting thus introduces noise rather than corrective signal (representative cases in Appendix~\ref{app:case-studies}; Appendix~\ref{app:subpopulation}).

\begin{figure*}[t]
\centering
\includegraphics[width=\textwidth]{figures/fig3_causal_dag_v11.pdf}
\caption{Causal DAG of the self-extraction pipeline. Traces $T$ produce both answers $A$ and constraints $C$; under degeneration (Observation~1), $C$ is determined by $A$ (dashed arrow), yielding $I(C;Y) \leq I(A;Y)$.}
\label{fig:causal-dag}
\end{figure*}

\looseness=-1 Figure~\ref{fig:regime-scatter} reveals regime structure across SC baselines. Three regimes emerge: Type~C (SC $\leq 40\%$), where low accuracy causes error amplification; an intermediate band (50--60\%), containing the only positive trends; and Type~A (SC $\geq 60\%$), where symbolic confirmation bias dominates. Fleiss' $\kappa$ ranges from 0.19 to 0.82, yielding $K_{\text{eff}} = 1.20\text{--}3.94$ at $K = 12$ (Table~\ref{tab:independence}; Appendix~\ref{app:cross-model-kappa}). Seed-level noise is substantial: across three Mistral-7B seeds, $\Delta$ ranges from $+2.94$ to $-2.45$\,pp despite $\kappa \in [0.45, 0.46]$. We trace the mechanism in \S\ref{sec:analysis}.

\looseness=-1 We use TOST equivalence tests \citep{lakens2017equivalence} with margin $\pm 2$\,pp, justified on four grounds: (1)~on FOLIO ($n{=}204$), $\pm$2\,pp corresponds to ${\sim}$4 problems, near single-item influence; (2)~multi-seed SC variability $\sigma_{\text{SC}} = 1.67$--$2.51$\,pp on FOLIO, with $\sigma_\Delta$ up to 2.70\,pp (Table~\ref{tab:multi-seed}), placing $\pm$2\,pp within natural noise; (3)~the observed $|\Delta|$ median across 11 conditions is 1.47\,pp, so $\pm$2\,pp captures the central tendency; (4)~sensitivity analysis confirms $\pm$2\,pp as the narrowest discriminating window ($\pm$1\,pp: zero conditions pass; $\pm$3\,pp: all pass; Appendix~\ref{app:tost}). Four of 11 conditions pass TOST equivalence (minimum detectable effect (MDE) $\leq 2$\,pp); the remaining seven are underpowered (MDE $4.6$--$4.8$\,pp) but provide consistent directional evidence ($|\Delta| \leq 4.41$\,pp, none significant; Appendix~\ref{app:power}). Multi-seed replication: mean $\Delta = +0.16 \pm 2.70$\,pp across three Mistral-7B seeds (Table~\ref{tab:multi-seed}); four Qwen2.5-14B seeds yield $\Delta \in [0.00, -2.01]$\,pp; four Qwen3-14B seeds yield $\Delta = +0.92 \pm 1.14$\,pp (n.s.; Appendix~\ref{app:single-trace}). Oracle controls confirm the MAX-SAT mechanism is sound ($+29.90$/$+13.73$\,pp FOLIO, $+17.17$\,pp ProofWriter; $p < 0.001$), yet self-extraction captures only ${\sim}12\%$ of this ceiling (Appendix~\ref{app:oracle}; Appendix~\ref{app:pw-oracle-subtype}).

\section{Introduction}\label{sec:introduction}

\looseness=-1
Self-Consistency (SC) \citep{wang2023sc} selects the majority answer across $K$ chain-of-thought traces, a strategy grounded in the Condorcet Jury Theorem: independent voters converge to truth \citep{condorcet1785, ladha1992correlated}. In practice, SC's gains plateau for strong models \citep{loo2025reevaluating, byerly2025selfconsistency}, and correlated LLM errors \citep{kim2025correlated} reduce the effective ensemble size \citep{dietterich2000ensemble}. A natural remedy is to move beyond simple vote-counting: extract logical constraints from the traces, as in neuro-symbolic approaches \citep{pan2023logiclm, olausson2023linc, ye2024satlm}, and let a provably sound solver adjudicate. If the solver can filter contradictions and enforce logical consistency, it should recover information that raw majority voting discards.

\begin{figure*}[t!]
\centering
\includegraphics[width=\textwidth]{figures/fig1_pipeline_v10.pdf}
\caption{The SICA pipeline. SC selects the majority answer from $K$ traces. SICA extracts logical constraints, deduplicates, and solves MAX-SAT via Z3. Red dashed box: the independence bottleneck. Dashed arrow: oracle variant with gold FOL.}
\label{fig:pipeline}
\end{figure*}

\looseness=-1
We test this intuition through Symbolic Invariant Consensus Aggregation (SICA), which extracts logical constraints from reasoning traces, deduplicates them, and selects answers via weighted partial MAX-SAT (\S\ref{sec:pipeline}; Figure~\ref{fig:pipeline}). Across six models (7B--32B), four benchmarks, and multi-seed replication, SICA produces answers identical to majority voting on most problems; no condition shows a significant positive effect after FDR control (Table~\ref{tab:main_results}). The failure lies not in the solver but in the constraints it operates on: self-extracted constraints systematically support the model's majority answer, a robust empirical regularity we term \emph{symbolic confirmation bias} (\S\ref{sec:confirmation-bias}), distinct from trace-level unfaithfulness \citep{turpin2023language, wan2025unveiling}. Because each trace determines both an answer and its constraints, the formal verification channel approximately reduces to a weighted echo of the majority vote under the degeneration condition (Observation~1).

\looseness=-1
This bias is not confined to a single model or task. Symbolic confirmation bias holds across nine models from 7B to frontier scale, and 27 training-free remediation strategies spanning four categories (prompt diversity, constraint filtering, multi-agent debate, and cross-model extraction) all produce neutral-to-negative results (\S\ref{sec:remediation}). A persistent independence--accuracy trade-off emerges: methods that break trace correlation (e.g., multi-agent debate; \citealp{liang2023encouraging, du2023improving}) destroy accuracy, while methods that preserve accuracy fail to achieve independence. Prior work demonstrates that LLMs cannot self-correct reasoning without external feedback \citep{huang2024selfcorrect, kamoi2024selfcorrect}; our analysis provides a concrete mechanism for these findings via the $M{\to}T{\to}(A,C)$ generation structure, where constraints are downstream of the same generative process that produces the answers they are meant to check.

\looseness=-1
The bottleneck lies in self-extraction itself, not in solver capability or model scale. Cross-architecture verification provides preliminary evidence of escape ($n{=}6$ generator--verifier pairs, exploratory): a structurally independent verifier yields significant gains when it exceeds the generator's accuracy, with benefit governed by a capability-gap pattern between verifier and generator (\S\ref{sec:cross-arch}). This result parallels test-time compute scaling \citep{snell2025scaling}, where additional inference budget faces diminishing returns once effective ensemble diversity saturates. Three lightweight diagnostics derived from a pilot run enable practitioners to predict a priori whether a self-extraction-based aggregation method will improve over SC (\S\ref{sec:diagnostic-framework}).
